def give_customers_their_money(apps, schema_editor):
    Customer = apps.get_model("crm", "Customer")
    Lead = apps.get_model("crm", "Lead")
    Payment = apps.get_model("crm", "Payment")
    for customer in Customer.objects.filter(price__isnull=True):
        leads = list(Lead.objects.filter(converted_customer=customer))
        values = [lead.value for lead in leads if lead.value is not None]
        if values:
            customer.price = sum(values)
            customer.save(update_fields=["price"])
        for lead in leads:
            if lead.amount_paid and not Payment.objects.filter(lead=lead).exists():
                Payment.objects.create(
                    customer=customer, lead=lead, amount=lead.amount_paid,
                    received_on=(lead.converted_at.date() if lead.converted_at
                                 else customer.customer_since),
                    method="other",
                    notes="Paid before payments were recorded one by one.")


